        if (input.required && !input.value.trim()) {
            isValid = false;
            errorMessage = `${labelText} is required.`;
        } else if (input.type === 'email' && input.value.trim()) {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(input.value.trim())) {
                isValid = false;
                errorMessage = 'Please enter a valid email address.';
            }
        } else if (input.type === 'tel' && input.value.trim()) {
            const phoneRegex = /^[\+]?[(]?[0-9]{1,4}[)]?[-\s\./0-9]*$/;
            if (!phoneRegex.test(input.value.trim()) || input.value.trim().replace(/\D/g, '').length < 10) {
                isValid = false;
                errorMessage = 'Please enter a valid phone number matching the requested format.';
            }
        }

        if (!isValid) {
            input.setAttribute('aria-invalid', 'true');
            errorElement.textContent = errorMessage;
            errorElement.removeAttribute('hidden');

            const describedBy = [];
            if (helpElement) describedBy.push(helpElement.id);
            describedBy.push(errorElement.id);

            input.setAttribute('aria-describedby', describedBy.join(' '));
        } else {
            input.removeAttribute('aria-invalid');
            errorElement.setAttribute('hidden', '');

            if (helpElement) {
                input.setAttribute('aria-describedby', helpElement.id);
            } else {
                input.removeAttribute('aria-describedby');
            }
        }

        return isValid;
    };

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        // Reset global status message
        statusMessage.setAttribute('hidden', '');
        statusMessage.className = 'status-message';
        statusMessage.textContent = '';

        let isFormValid = true;
        let firstInvalidInput = null;

        const formFields = form.querySelectorAll('.form-field');

        formFields.forEach(field => {
            const isValid = validateField(field);
            if (!isValid) {
                isFormValid = false;
                if (!firstInvalidInput) {
                    firstInvalidInput = field.querySelector('input');
                }
            }
        });

        // Set focus to the first invalid field for keyboard/screen reader users
        if (!isFormValid) {
            firstInvalidInput.focus();
        } else {
            // Simulated successful submission
            statusMessage.textContent = 'Your support request has been submitted successfully.';
            statusMessage.classList.add('success');
            statusMessage.removeAttribute('hidden');
            form.reset();

            // Clean up attributes after reset
            formFields.forEach(field => {
