            // Clean up attributes after reset
            formFields.forEach(field => {
                const input = field.querySelector('input');
                const helpElement = field.querySelector('.help-text');
                input.removeAttribute('aria-invalid');
                if (helpElement) {
                    input.setAttribute('aria-describedby', helpElement.id);
                } else {
                    input.removeAttribute('aria-describedby');
                }
            });
        }
    });

    // Automatically revalidate a field on input *only after* an error has been shown
    const inputs = form.querySelectorAll('input');
    inputs.forEach(input => {
        input.addEventListener('input', () => {
            if (input.hasAttribute('aria-invalid')) {
                validateField(input.closest('.form-field'));
            }
        });
    });
});    </script>
</body>
</html>
